with filtered_web_events as (select * from web_events where (event_type in ('purchase', 'add_to_cart', 'search') and hour(event_time) between 7 and 13) or event_type = 'add_to_cart'), summary as (select month(event_time) as event_month, min(event_time) as min_event_time, count(distinct duration_sec) as unique_sessions from filtered_web_events group by month(event_time)) select event_month, unique_sessions from summary order by event_month desc limit 1;
